var n=`0382-erwtensoep`;var i=`world-0382`;var a=`NL`;var r=`western-europe`;var s=4;var o=140;var l={en:`Erwtensoep`,ua:`Ервтенсуп`};var g={en:`A traditional Netherlands dish made with green split peas, yellow onion, carrot, celeriac. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Нідерланди. Основні інгредієнти: зелений колотий горох, жовта цибуля, морква, корінь селери. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Cook the listed ingredients in simmering water for about 95 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 95 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:95,i:[[`green-split-peas`,420,`g`],[`water`,1500,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,170,`g`],[`carrot`,200,`g`],[`celeriac`,180,`g`],[`leek`,170,`g`]]},{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 9 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 9 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:9,i:[[`bratwurst`,340,`g`],[`bacon`,180,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`bay-leaf`,2,`leaf`],[`table-salt`,null,`to_taste`]]}];var u={slug:n,id:i,country:`NL`,region:r,servings:4,minutes:140,title:l,text:g,steps:d};export{a as country,u as default,i as id,o as minutes,r as region,s as servings,n as slug,d as steps,g as text,l as title};